import {THEMES,CHALLENGES,musicQuestions,shuffle} from './catalog.js';
import {createGame,applyAction,publicGame,DEMO,targets,gameSettings} from './engine.js';
import {SoundDesk,storeBlob,getBlob} from './audio.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}};
const write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let config=read('declic.config',{universe:'music',mode:'usb',input:'qcm',effect:'normal',source:'demo',teams:[{id:'0',name:'Les Disco',key:'1'},{id:'1',name:'Les Rockstars',key:'2'},{id:'2',name:'Les Paillettes',key:'3'},{id:'3',name:'Les Incollables',key:'4'}]});
let custom=read('declic.library',[]), view='home', game=null, room=null, ws=null, role='host', teamId=null, connected=false, reconnect=null, auth=null, lastEvent=null, seenCount=null, countdown=-1, lastRevision=-1, assetUrls=new Map(), audioReady=false, soundTask=0, busy=false;
let catalogPool=read('declic.musicPool',{name:'',tracks:[],themeKey:''}),catalogResults={tracks:[],playlists:[]},catalogQuery='',catalogSearchType='tracks',catalogMessage='',audioError='',replyDraft={};
const newDefaults={themes:['fr'],count:10,duration:30,difficulty:'balanced',challenge:'title',explicit:false,settings:gameSettings()};
for(const [key,value]of Object.entries(newDefaults))if(config[key]===undefined)config[key]=value;
config.settings=gameSettings(config.settings);if(config.version!==2){config.source='catalog';config.version=2;write('declic.config',config);}
const desk=new SoundDesk();
const effects=[['normal','🎧','Classique','L’extrait original','#e6e1ff'],['fast','⏩','Accéléré','Tout va plus vite','#ffe3cd'],['slow','🐢','Ralenti','Prenez votre temps','#e4f3cb'],['chipmunk','🐿️','Voix écureuil','Aiguë et accélérée','#ffe2ef'],['reverse','↶','À l’envers','Les repères s’envolent','#deedff'],['image','▧','Image mystère','Du flou au déclic','#fbe9be']];
const colors=['#e9ddff','#ffdfc9','#e4f1bc','#ffd9e9','#d5ecff','#ffeaa9','#d1f3e7','#e7ddf6','#ffdbd3','#d9e7f8'];
const icons=['🪩','🎸','✨','⚡','🎬','🎤','🚀','🍿','🦄','🏆'];
let channel=new BroadcastChannel('declic-screen');
channel.onmessage=e=>{if(e.data.type==='request'&&game&&role==='host')broadcastTV();if(e.data.type==='state'&&role==='tv'&&!room){game=e.data.state;receive();}};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=$('#confetti');el.innerHTML=Array.from({length:55},(_,i)=>`<i class="confetto" style="left:${Math.random()*100}%;background:${['#e2f889','#ff925b','#ffc6e0','#9f7af3','#79c5ed'][i%5]};animation-delay:${Math.random()*.5}s;animation-duration:${2+Math.random()}s;transform:rotate(${i*27}deg)"></i>`).join('');setTimeout(()=>el.replaceChildren(),4000);}
function saveConfig(){write('declic.config',config);}
function brand(){return '<button class="brand" data-action="home" aria-label="Déclic ! Accueil"><span>ϟ</span>Déclic !</button>';}
function header(){return `<header class="topbar">${brand()}<nav class="nav" aria-label="Navigation principale"><button class="${view==='home'||view==='studio'?'active':''}" data-action="home">Le studio</button><button class="${view==='catalog'?'active':''}" data-action="v2-catalog">Les musiques</button><button class="${view==='library'?'active':''}" data-action="library">Mes questions</button><button class="${view==='help'?'active':''}" data-action="help">Comment jouer</button></nav><span class="pill"><span class="dot"></span> La bonne humeur est prête</span></header>`;}
function footer(){return '<footer class="footer"><span>Un peu de culture. Beaucoup de déclics.</span><span>Déclic ! · Le studio de vos soirées · v0.2</span></footer>';}
function selectedQuestions(){if(config.source==='catalog'&&config.universe==='music')return musicQuestions(catalogPool.tracks,config);return(config.source==='custom'?custom:DEMO).filter(q=>q.universe===config.universe).slice(0,config.count);}
function render(){
 if($('#catalog-player'))desk.stop();
 const form=$('#answer-form');if(form&&currentQ())replyDraft[form.dataset.question||currentQ().id]={...replyDraft[form.dataset.question||currentQ().id],...Object.fromEntries(new FormData(form))};
 const a=$('#app');
 if(role==='tv'){a.innerHTML=tvScreen();return;}
 if(view==='join'){a.innerHTML=joinScreen();return;}
 if(role==='player'&&view!=='history'){a.innerHTML=phoneScreen();return;}
 a.innerHTML=`<div class="shell">${header()}${view==='home'?home():view==='catalog'?catalogScreen():view==='history'?historyScreen():view==='library'?library():view==='help'?help():studio()}${footer()}</div>`;
 if(view==='studio')void prepareImage();
}
function home(){const qs=selectedQuestions(),isMusic=config.universe==='music';return `<div class="workspace"><main class="maincol"><section class="hero"><span class="eyebrow">LE JEU QUI MET LA SALLE EN MOUVEMENT</span><span class="tag">Prêts pour le déclic ?</span><h1>Les tubes passent.<br><em>À vous de jouer.</em></h1><p>Musique, cinéma et défis décalés.<br>Vos équipes, vos règles, votre soirée.</p><div class="hero-art" aria-hidden="true"><div class="record"></div><span class="note">♫</span><span class="spark">✦</span></div></section><div class="sectiontitle"><h2><span class="step">1</span>Votre terrain de jeu</h2></div><div class="universe-grid">${[['music','♫','Musique','Titres, artistes & pochettes'],['film','🎬','Cinéma','Films, répliques & images']].map(([id,icon,title,sub])=>`<button class="universe ${id==='film'?'film':''} ${config.universe===id?'selected':''}" data-action="universe" data-value="${id}" aria-pressed="${config.universe===id}"><span class="uicon">${icon}</span><div><h3>${title}</h3><p>${sub}</p></div><span class="check">${config.universe===id?'✓':''}</span></button>`).join('')}</div>${isMusic?`<div class="sectiontitle"><h2><span class="step">2</span>Composez votre sélection</h2><small>Jusqu’à 3 ambiances à mélanger</small></div><div class="theme-grid">${THEMES.map(([id,icon,title,sub])=>`<button class="theme-card ${config.themes.includes(id)?'active':''}" data-action="v2-theme" data-value="${id}" aria-pressed="${config.themes.includes(id)}"><span>${icon}</span><strong>${title}</strong><small>${sub}</small>${config.themes.includes(id)?'<b>✓</b>':''}</button>`).join('')}</div><div class="catalog-banner"><div><strong>Vos prochains refrains sont ici.</strong><p>Recherchez un artiste, choisissez des titres ou importez une playlist Deezer.</p></div><button class="btn ghost" data-action="v2-catalog">Explorer les musiques ↗</button></div><div class="sectiontitle"><h2><span class="step">3</span>À vous de deviner…</h2></div><div class="challenge-grid">${CHALLENGES.filter(([id])=>id!=='both'||config.mode==='usb'||config.input==='text').map(([id,icon,title])=>`<button class="challenge ${config.challenge===id?'active':''}" data-action="v2-challenge" data-value="${id}" aria-pressed="${config.challenge===id}"><span>${icon}</span>${title}</button>`).join('')}</div>`:'<div class="callout">Les questions de découverte cinéma sont prêtes. Ajoutez vos propres images, extraits audio ou répliques dans « Mes questions ».</div>'}<div class="sectiontitle"><h2><span class="step">${isMusic?'4':'2'}</span>Un grain de folie</h2><small>Appliqué aux extraits audio ou images</small></div><div class="effect-grid">${effects.map(([id,icon,title,sub,tint])=>`<button class="effect ${config.effect===id?'active':''}" data-action="effect" data-value="${id}" aria-pressed="${config.effect===id}"><span class="icon" style="--tint:${tint}">${icon}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div><div class="bottomstrip"><span>✦ <strong>Une soirée à votre image.</strong> Les questions et fichiers personnels restent disponibles.</span><button class="textbtn" data-action="library">Préparer mes questions ↗</button></div></main><aside class="sidebar"><span class="eyebrow">LE STUDIO</span><h2>Les règles du jeu</h2><div class="segmented"><button data-action="mode" data-value="usb" class="${config.mode==='usb'?'active':''}">◉ Buzzers USB</button><button data-action="mode" data-value="phone" class="${config.mode==='phone'?'active':''}">▯ Téléphones</button></div><p class="help">${config.mode==='usb'?'Les équipes buzzent. Vous validez le titre, l’artiste ou les deux.':'Un code à partager. Les équipes répondent et les points sont calculés automatiquement.'}</p>${config.mode==='phone'?`<label class="field-label" for="inputmode">Réponse sur téléphone</label><select id="inputmode"><option value="qcm" ${config.input==='qcm'?'selected':''}>QCM · 4 choix</option><option value="text" ${config.input==='text'?'selected':''}>Écrit · titre et artiste séparés</option></select>`:`<span class="field-label">Les équipes · touches personnalisables</span>${config.teams.map((t,i)=>`<div class="teamrow"><span class="avatar" style="--team:${colors[i]}">${icons[i]}</span><input aria-label="Nom de l’équipe ${i+1}" data-team="${i}" value="${esc(t.name)}" maxlength="24"><input class="customkey" aria-label="Touche de l’équipe ${i+1}" data-key="${i}" value="${esc(t.key)}" maxlength="1"><button class="iconbtn" aria-label="Retirer l’équipe ${i+1}" data-action="remove-team" data-value="${i}" ${config.teams.length<=2?'disabled':''}>×</button></div>`).join('')}<button class="textbtn" data-action="add-team" ${config.teams.length>=10?'disabled':''}>＋ Ajouter une équipe</button>`}<div class="divider"></div><label class="field-label" for="source">Les contenus</label><select id="source">${isMusic?`<option value="catalog" ${config.source==='catalog'?'selected':''}>Catalogue · extraits Deezer</option>`:''}<option value="custom" ${config.source==='custom'?'selected':''}>Mes questions personnelles</option><option value="demo" ${config.source==='demo'||!isMusic&&config.source==='catalog'?'selected':''}>Découverte · démonstration</option></select>${config.source==='catalog'&&isMusic?`<p class="mini" style="margin-top:10px">${catalogPool.tracks.length?`${catalogPool.tracks.length} titres chargés · ${esc(catalogPool.name)}`:'Vos thèmes seront chargés au lancement.'}</p><button class="textbtn" data-action="v2-load-themes" ${busy?'disabled':''}>↻ Charger les thèmes choisis</button>`:`<p class="mini" style="margin-top:10px">${qs.length} questions disponibles dans cet univers.</p>`}<div class="two-fields"><label>Questions<select data-config="count">${[5,10,15,20].map(n=>`<option ${config.count===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Durée<select data-config="duration">${[10,15,20,30].map(n=>`<option value="${n}" ${config.duration===n?'selected':''}>${n} s</option>`).join('')}</select></label></div>${isMusic?`<label class="field-label" for="difficulty">Sélection des titres</label><select id="difficulty" data-config="difficulty"><option value="easy" ${config.difficulty==='easy'?'selected':''}>Les plus populaires</option><option value="balanced" ${config.difficulty==='balanced'?'selected':''}>Un mélange équilibré</option><option value="hard" ${config.difficulty==='hard'?'selected':''}>Des titres moins connus</option></select>`:''}<details class="settings-details"><summary>⚙ Points et déroulement</summary><div class="two-fields"><label>Points titre<input type="number" min="1" max="1000" data-setting="titlePoints" value="${config.settings.titlePoints}"></label><label>Points artiste<input type="number" min="1" max="1000" data-setting="artistPoints" value="${config.settings.artistPoints}"></label></div><label class="checkboxline"><input type="checkbox" data-setting="speed" ${config.settings.speed?'checked':''}> Bonus de rapidité · jusqu’à 50 pts</label><label class="checkboxline"><input type="checkbox" data-setting="streak" ${config.settings.streak?'checked':''}> Bonus de série · jusqu’à 50 pts</label>${config.mode==='usb'?`<label class="field-label">Après une mauvaise réponse<select data-setting="rebuzz">${[['round','Bloqué pour cette question'],['none','Rebuzz immédiat'],['3','Rebuzz après 3 secondes'],['5','Rebuzz après 5 secondes'],['10','Rebuzz après 10 secondes']].map(([id,name])=>`<option value="${id}" ${config.settings.rebuzz===id?'selected':''}>${name}</option>`).join('')}</select></label><label class="field-label">Reprise de la musique<select data-setting="resume"><option value="auto" ${config.settings.resume==='auto'?'selected':''}>Automatique après validation</option><option value="manual" ${config.settings.resume==='manual'?'selected':''}>Manuelle · je garde la main</option></select></label>`:''}<label class="checkboxline"><input type="checkbox" data-setting="autoNext" ${config.settings.autoNext?'checked':''}> Question suivante après 8 secondes</label><label class="checkboxline"><input type="checkbox" data-config="explicit" ${config.explicit===false?'checked':''}> Exclure les titres marqués explicites</label></details>${catalogMessage?`<div class="catalog-message" role="status">${esc(catalogMessage)}</div>`:''}<button class="btn primary full" data-action="launch" ${busy?'disabled':''}>${busy?'Préparation des extraits…':'Lancer la soirée →'}</button><p class="caption">${config.mode==='usb'?'2 à 10 équipes · clavier ou buzzer qui émule une touche':'Jusqu’à 50 équipes · Internet nécessaire'}<br>${isMusic&&config.source==='catalog'?'Extraits de 30 s maximum. Disponibilité selon Deezer.':'Vos contenus personnels restent sur ce PC.'}</p></aside></div><div class="row" style="margin-bottom:25px"><button class="textbtn" data-action="join-page">Rejoindre une partie →</button>${read('declic.host',null)?'<button class="textbtn" data-action="resume-phone">Reprendre ma partie téléphones</button>':''}${read('declic.localGame',null)?'<button class="textbtn" data-action="resume">Reprendre ma partie USB</button>':''}${game?'<button class="textbtn" data-action="v2-return">Revenir à la partie en cours</button>':''}</div>`;}
function library(){return `<main class="library"><div class="row"><div><span class="eyebrow">LA BOÎTE À IDÉES</span><h1>Vos questions. Votre ambiance.</h1><p class="help">Préparez vos extraits et vos indices. Les fichiers restent dans ce navigateur.</p></div><button class="btn primary right" data-action="new-question">＋ Nouvelle question</button></div><div class="row"><button class="btn ghost" data-action="export">Exporter les questions JSON</button><label class="btn ghost">Importer un JSON<input type="file" id="import-json" accept="application/json" hidden></label></div><div class="cards">${custom.map(q=>`<article class="qcard"><span class="badge">${q.universe==='music'?'MUSIQUE':'CINÉMA'} · ${q.kind==='audio'?'EXTRAIT':q.kind==='image'?'IMAGE':'QUESTION'}</span><div class="emoji" style="margin-top:16px">${q.kind==='audio'?'🎧':q.kind==='image'?'🖼️':'💡'}</div><h3>${esc(q.prompt)}</h3><p>Réponse : <strong>${esc(q.answer)}</strong><br>${q.duration} secondes · ${q.points} points</p><div class="row" style="margin-top:16px"><button class="textbtn" data-action="edit-question" data-value="${esc(q.id)}">Modifier</button><button class="textbtn right" data-action="delete-question" data-value="${esc(q.id)}">Retirer</button></div></article>`).join('')||'<div class="empty wide">La piste est à vous !<br>Ajoutez une première question pour créer votre blind test.</div>'}</div><div class="callout">Les réponses écrites acceptent les accents et la ponctuation indifféremment. Ajoutez des réponses alternatives dans l’éditeur. L’export JSON contient les questions, pas les fichiers audio ou images.</div></main>`;}
function help(){return `<main class="help-page"><span class="eyebrow">LA RECETTE D’UNE BONNE SOIRÉE</span><h1>Moins de réglages. Plus de jeu.</h1><div class="cards"><article class="qcard"><div class="emoji">🎛️</div><h3>1. Préparez</h3><p>Choisissez musique ou cinéma, un effet et votre sélection. Testez les questions de découverte ou importez vos extraits.</p></article><article class="qcard"><div class="emoji">⚡</div><h3>2. Faites buzzer</h3><p>En USB, l’animateur lance l’extrait. La première touche coupe le son. Bonne réponse : des points ! Mauvaise réponse : l’équipe est bloquée pour cette question et le son reprend.</p></article><article class="qcard"><div class="emoji">🏆</div><h3>3. Célébrez</h3><p>Révélez la réponse, affichez le classement et passez à la suite. La partie se termine par le podium.</p></article></div><div class="qcard" style="margin-top:20px"><h3>Le PC + la TV</h3><p>Cliquez sur « Écran public ». Déplacez cette fenêtre sur la TV et mettez-la en plein écran. Gardez les commandes sur le PC. Le son sort uniquement du PC animateur.</p><h3 style="margin-top:25px">Les buzzers USB</h3><p>Cette ébauche accepte les buzzers qui envoient une touche de clavier. Configurez une touche différente par équipe dans le studio. Les modèles qui se présentent uniquement comme des manettes nécessiteront une prise en charge supplémentaire. Le navigateur doit avoir le focus.</p><h3 style="margin-top:25px">Les téléphones</h3><p>Créez une partie en mode téléphones et partagez le lien ou le code. Les équipes répondent en QCM ou par écrit. La correction est automatique : titre et artiste sont indépendants. La rapidité et les séries peuvent ajouter chacune jusqu’à 50 points. Cinq essais maximum par manche écrite ; une seule réponse en QCM. Les points sont affichés à la révélation. Internet est nécessaire pour ce premier mode connecté.</p><h3 style="margin-top:25px">Vos fichiers et les effets</h3><p>Importez un MP3, WAV ou autre audio compatible avec votre navigateur, ou une image. Les effets accéléré, ralenti, écureuil et envers agissent sur l’audio. L’effet écureuil augmente la vitesse et la hauteur ensemble. L’image mystère révèle progressivement les détails. Pour compléter des paroles ou une réplique, saisissez votre question et les mots attendus.</p><h3 style="margin-top:25px">Ce qui arrive plus tard</h3><p>Le catalogue Deezer est connecté : recherche de titres et de playlists, thèmes à mélanger et extraits de 30 secondes maximum. Le QR code, les bandes-annonces vidéo, le réseau local sans Internet et les buzzers de type manette restent à venir.</p><p style="margin-top:20px">Utilisez des contenus que vous êtes autorisé à diffuser. Les parties connectées expirent après 24 heures. Les questions personnelles et les médias restent sur le PC ; seul le texte utile au jeu est partagé dans la partie.</p></div></main>`;}
function currentQ(){return game?.question||game?.questions?.[game.index];}
function sorted(){return [...(game?.teams||[])].sort((a,b)=>b.score-a.score);}
function timerMarkup(){return '<div class="timer"><span data-time>—</span><div class="timer-track"><div class="timer-fill" data-progress></div></div></div>';}
function stage(){if(!game)return '<div class="empty">En attente de l’animateur…</div>';const q=currentQ(),phase=game.phase,total=game.total||game.questions?.length||0;
 if(phase==='finished')return `<div class="stage-content"><span class="eyebrow">LE DERNIER MOT EST POUR VOUS</span><h1>Les champions du déclic !</h1><div class="podium">${sorted().slice(0,3).map((t,i)=>`<div><span style="font-size:35px">${['🏆','🥈','🥉'][i]}</span><strong>${esc(t.name)}</strong><span>${t.score} points</span></div>`).join('')}</div><p class="help">${total} manches. Bravo à toutes les équipes !</p></div>`;
 if(phase==='lobby')return `<div class="stage-content"><span class="eyebrow">PRÊTS À FAIRE LE DÉCLIC ?</span><div class="big-emoji">${q?.universe==='film'?'🍿':'🪩'}</div><h1>La soirée commence ici.</h1><p class="help">${game.mode==='phone'?`Rejoignez avec le code <strong style="color:var(--lime);font-size:27px;letter-spacing:4px">${esc(room)}</strong>`:'Installez vos équipes et testez vos touches !'}</p><p class="mini" style="color:#c4b2dc">${game.teams.length} équipe(s) · ${total} questions</p></div>`;
 const reveal=phase==='reveal',count=phase==='playing'&&Date.now()<game.startAt?Math.ceil((game.startAt-Date.now())/1000):0;const art=q?.artwork&&(q.target==='cover'||game.effect==='image'||reveal);
 return `<span class="counter">${game.index+1} / ${total}</span><div class="stage-content"><span class="eyebrow">${q?.universe==='film'?'CINÉMA':'MUSIQUE'} · ${CHALLENGES.find(v=>v[0]===q?.target)?.[2]||'LE DÉFI'}</span>${count?`<h1 class="countdown">${count}</h1><p class="help">À vos marques…</p>`:`<h1>${esc(q?.prompt)}</h1>${q?.target==='artistTitle'?`<div class="artist-cue">${esc(q.artist||q.displayArtist)}</div>`:''}${art?`<img src="${esc(q.artwork)}" alt="Pochette à identifier" ${q.target==='cover'||game.effect==='image'?'data-mystery':''}>`:q?.mediaKey&&q.kind==='image'||q?.imageUrl?'<div data-image></div>':q?.emoji?`<div class="big-emoji" data-mystery>${esc(q.emoji)}</div>`:q?.kind==='audio'?'<div class="record" aria-hidden="true"></div>':''}${phase==='buzzed'?`<div class="buzz-banner">⚡ ${esc(game.teams.find(t=>t.id===game.buzz)?.name)} a buzzé !</div>`:''}${phase==='paused'?'<div class="pause-banner">Ⅱ En pause · l’animateur garde la main</div>':''}${reveal?`<span class="eyebrow">LA RÉPONSE</span><h2>${esc(q.title||q.answer)}</h2>${q.artist?`<p class="reveal-artist">${esc(q.artist)}</p>`:''}${q.provider?`<a class="source-credit" href="${esc(q.link)}" target="_blank" rel="noopener noreferrer">Extrait fourni par Deezer · écouter le titre ↗</a>`:''}`:phase==='ready'?'<p class="help">Une nouvelle question vous attend.</p>':''}${!reveal&&game.input==='qcm'&&game.mode==='phone'&&q?.options?.length?`<div class="options">${q.options.map((o,i)=>`<div class="option"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</div>`).join('')}</div>`:''}${timerMarkup()}`}</div>`;
}
function scorebar(){return `<div class="scorebar">${(game?.teams||[]).map((t,i)=>`<div class="scorecard"><span class="avatar" style="--team:${colors[i%10]}">${icons[i%10]}</span><span>${esc(t.name)}</span><strong>${t.score}</strong></div>`).join('')}</div>`;}
function leaderboard(){return sorted().map((t,i)=>`<div class="leaderrow"><span class="rank">${i+1}</span><span class="avatar" style="--team:${colors[(game.teams.findIndex(v=>v.id===t.id)+10)%10]}">${icons[(game.teams.findIndex(v=>v.id===t.id)+10)%10]}</span><span>${esc(t.name)}${t.streak>1?` <small class="streak">🔥${t.streak}</small>`:''}</span><span class="pts">${t.score}</span></div>`).join('');}
function studio(){if(!game)return '<div class="empty">Aucune partie en cours.</div>';const q=currentQ(),ph=game.phase,wanted=q?targets(q):[],claimed=game.claimed||{};return `<main class="studio"><div class="row"><span class="eyebrow">LE STUDIO · ${game.mode==='usb'?'BUZZERS USB':'TÉLÉPHONES'}</span><span class="connection ${game.mode==='phone'&&!connected?'offline':''}">${game.mode==='phone'?(connected?'● Connecté':'○ Reconnexion…'):'● Partie sur ce PC'}</span><button class="btn ghost right" data-action="screen">▣ Écran public</button><button class="btn ghost" data-action="sound">${desk.muted?'♪ Jingles coupés':'♫ Jingles actifs'}</button></div><div class="game-layout"><section class="stage ${ph==='playing'?'playing':''}" aria-live="polite">${stage()}</section><aside class="control"><h3>${ph==='lobby'?'Tout le monde est là ?':ph==='finished'?'Quelle soirée !':'À vous les commandes'}</h3>${game.mode==='phone'&&ph==='lobby'?`<p class="help">Partagez le code avec vos équipes :</p><div class="answerbox room-code">${esc(room)}</div><button class="btn ghost full" data-action="copy-link">Copier le lien d’invitation</button>`:''}${!['lobby','finished'].includes(ph)?`<div class="answerbox"><small>RÉPONSE · ANIMATEUR</small><strong>${esc(q.title||q.answer)}</strong>${q.artist?`<br>${esc(q.artist)}`:''}</div>`:''}${['lobby','ready'].includes(ph)?`<button class="btn primary full" data-action="play" ${busy||game.mode==='phone'&&!game.teams.length?'disabled':''}>${busy?'Chargement de l’extrait…':'▶ '+(ph==='lobby'?'Lancer la partie':'Lancer l’extrait')}</button>`:''}${ph==='buzzed'?`${wanted.length===2?`<div class="judge-grid"><button class="btn good" data-action="v2-judge" data-value="title" ${claimed.title?'disabled':''}>✓ Titre</button><button class="btn good" data-action="v2-judge" data-value="artist" ${claimed.artist?'disabled':''}>✓ Artiste</button></div><button class="btn good full" data-action="good">✓ Les deux</button>`:'<button class="btn good full" data-action="good">✓ Bonne réponse</button>'}<button class="btn bad full" data-action="bad">✕ Mauvaise réponse</button>`:''}${ph==='playing'?'<button class="btn ghost full" data-action="pause">Ⅱ Mettre en pause</button>':''}${ph==='paused'?'<button class="btn lime full" data-action="resume">▶ Reprendre la musique</button>':''}${['playing','buzzed','paused'].includes(ph)?'<button class="btn ghost full" data-action="reveal">Révéler et terminer la manche</button>':''}${ph==='reveal'?`<button class="btn primary full" data-action="next">${game.index+1>=(game.questions?.length||game.total)?'Le podium 🏆':'Question suivante →'}</button>${game.nextAt?'<p class="mini">La suite arrive automatiquement après 8 secondes.</p>':''}`:''}${ph==='finished'?'<button class="btn lime full" data-action="new-game">Préparer une autre partie</button>':''}${game.mode==='phone'&&ph==='playing'?`<p class="help">${Object.keys(game.answers||{}).length} / ${game.teams.length} équipe(s) ont répondu</p>`:''}${Object.keys(claimed).length?`<p class="mini">${claimed.title?'✓ Titre trouvé ':''}${claimed.artist?'✓ Artiste trouvé':''}</p>`:''}<div class="divider"></div><span class="eyebrow">LE CLASSEMENT</span>${leaderboard()}${game.teams.length?'<button class="textbtn" data-action="adjust">Ajuster un score</button>':''}${game.history?.length?'<button class="textbtn full" data-action="v2-history">Voir le détail des manches →</button>':''}</aside></div>${game.mode==='usb'?`<div class="keytips">${game.teams.map(t=>`<strong>[${esc(t.key)}]</strong> ${esc(t.name)}${game.blocked?.includes(t.id)?' · bloqué':''}`).join(' · ')}<br>Gardez la fenêtre du PC active pour recevoir les buzzers.</div>`:''}${audioError?`<div class="catalog-message">${esc(audioError)}</div>`:''}${q?.provider?'<p class="media-notice">Extrait Deezer diffusé par le PC animateur. Le titre complet est accessible après la révélation.</p>':''}</main>`;}
function tvScreen(){return `<main class="tv-shell"><div class="row">${brand()}<span class="right">L’ÉCRAN DE LA SOIRÉE</span><button class="btn" data-action="fullscreen">⛶ Plein écran</button></div><section class="stage ${game?.phase==='playing'?'playing':''}">${stage()}</section>${scorebar()}</main>`;}
function joinScreen(){return `<main class="phone-shell">${brand()}<div class="joincard"><span class="eyebrow">ON VOUS GARDAIT UNE PLACE</span><h1>Entrez dans la partie.</h1><p class="help">Un nom d’équipe, le code de l’animateur et à vous de jouer.</p><form id="join-form"><label class="field-label" for="join-code">Code de la partie</label><input id="join-code" name="code" required minlength="8" maxlength="8" autocapitalize="characters" placeholder="EX. ABCD2345" value="${esc(room||'')}" autocomplete="off"><label class="field-label" for="join-name">Votre équipe</label><input id="join-name" name="name" required maxlength="24" placeholder="Les rois du refrain" autocomplete="nickname"><button class="btn primary full" type="submit" ${busy?'disabled':''}>${busy?'Connexion…':'Rejoindre la soirée →'}</button></form></div><p class="caption">Le son est diffusé dans la salle par l’animateur.<br>Gardez cet écran ouvert pendant la partie.</p></main>`;}
function phoneScreen(){const q=currentQ(),me=game?.teams?.find(t=>t.id===teamId),ph=game?.phase,r=game?.me||{},parts=r.parts||[],locked=game?.input==='qcm'?(r.attempts||0)>=1:(r.attempts||0)>=5||q&&targets(q).every(p=>parts.includes(p));if(!game)return '<main class="phone-shell"><div class="empty">Connexion à la partie…</div></main>';const draft=replyDraft[q?.id]||{};return `<main class="phone-shell"><div class="row">${brand()}<span class="pill right">${esc(me?.name||'Mon équipe')} · ${me?.score||0} pts</span></div><span class="connection ${connected?'':'offline'}">${connected?'● Dans la partie':'○ Reconnexion en cours…'}</span><section class="stage"><div class="stage-content">${ph==='lobby'?'<div class="big-emoji">🙌</div><h1>Vous êtes dans la place !</h1><p class="help">L’animateur lance la partie dès que tout le monde est prêt.</p>':ph==='finished'?stage():ph==='reveal'?`<span class="eyebrow">LA BONNE RÉPONSE</span><h2>${esc(q.title||q.answer)}</h2><p class="reveal-artist">${esc(q.artist||'')}</p><div class="round-points">+${r.total||0} points</div>${scoreBreakdown(r)}${q.provider?`<a class="source-credit" href="${esc(q.link)}" target="_blank" rel="noopener noreferrer">Écouter sur Deezer ↗</a>`:''}`:ph==='ready'?'<div class="big-emoji">👀</div><h1>La suite arrive…</h1>':ph==='paused'?'<div class="big-emoji">Ⅱ</div><h1>Petite pause.</h1><p class="help">On reprend avec l’animateur.</p>':Date.now()<game.startAt?`<h1 class="countdown">${Math.max(1,Math.ceil((game.startAt-Date.now())/1000))}</h1><p class="help">À vos marques…</p>`:`<span class="eyebrow">QUESTION ${game.index+1} / ${game.total}</span><h1>${esc(q.prompt)}</h1>${q.displayArtist?`<div class="artist-cue">${esc(q.displayArtist)}</div>`:''}${(q.target==='cover'||game.effect==='image')&&q.artwork?`<img src="${esc(q.artwork)}" alt="Pochette mystère" data-mystery>`:''}${locked?'<div class="big-emoji">✉️</div><p class="help">Réponse enregistrée. Verdict à la révélation !</p>':game.input==='qcm'?`<div class="options">${q.options.map((o,i)=>`<button class="option" data-action="answer" data-value="${esc(o)}"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div>`:q.musical?`<form id="answer-form" data-question="${esc(q?.id)}" class="music-reply">${targets(q).map(part=>`<label>${part==='title'?'Le titre':'L’artiste'} ${parts.includes(part)?'✓':''}<input name="${part}" aria-label="${part==='title'?'Titre':'Artiste'}" placeholder="${part==='title'?'Le titre du morceau…':'Le nom de l’artiste…'}" maxlength="180" value="${esc(draft[part]||'')}" ${parts.includes(part)?'disabled':''} autocomplete="off"></label>`).join('')}<button class="btn lime full" type="submit">Valider ma réponse →</button></form><p class="help">${parts.length?'✓ Réponse partielle validée. Continuez !':r.attempts?'Pas encore… Vous pouvez réessayer.':'Titre et artiste peuvent être validés séparément.'} · ${r.attempts||0}/5 essais</p>`:`<form id="answer-form" data-question="${esc(q?.id)}" class="textreply"><input name="answer" aria-label="Votre réponse" placeholder="Votre réponse…" value="${esc(draft.answer||'')}" maxlength="180" required autocomplete="off"><button class="btn lime" type="submit">→</button></form>`}${timerMarkup()}`}</div></section><div class="control" style="margin-top:20px"><span class="eyebrow">LE CLASSEMENT</span>${leaderboard()}${game.history?.length?'<button class="textbtn" data-action="v2-history">Le détail des manches →</button>':''}</div></main>`;}
function questionForm(q={}){const editing=!!q.id;modal(`<div class="top"><h2>${editing?'Modifier':'Créer'} une question</h2><button class="iconbtn" data-action="close-modal" aria-label="Fermer">×</button></div><form id="question-form" data-id="${esc(q.id||'')}"><div class="formgrid"><label>Univers<select name="universe"><option value="music" ${q.universe!=='film'?'selected':''}>Musique</option><option value="film" ${q.universe==='film'?'selected':''}>Cinéma</option></select></label><label>Type de défi<select name="kind"><option value="audio" ${q.kind==='audio'||!q.kind?'selected':''}>Extrait audio</option><option value="image" ${q.kind==='image'?'selected':''}>Image à deviner</option><option value="question" ${q.kind==='question'?'selected':''}>Question, paroles ou réplique à compléter</option></select></label><label class="wide">La question<input name="prompt" required maxlength="300" placeholder="Quel est le titre de cet extrait ?" value="${esc(q.prompt||'')}"></label><label class="wide">La bonne réponse<input name="answer" required maxlength="180" value="${esc(q.answer||'')}"></label><label>Titre musical (facultatif)<input name="title" value="${esc(q.title||'')}"></label><label>Artiste musical (facultatif)<input name="artist" value="${esc(q.artist||'')}"></label><label class="wide">Trois mauvaises réponses pour le QCM<textarea name="wrong" rows="3" required placeholder="Une réponse par ligne">${esc((q.options||[]).filter(o=>o!==q.answer).join('\n'))}</textarea></label><label class="wide">Autres réponses acceptées à l’écrit <span class="mini">(séparées par ;)</span><input name="aliases" value="${esc((q.aliases||[]).join('; '))}"></label><label>Durée (secondes)<input name="duration" type="number" min="5" max="90" value="${q.duration||30}" required></label><label>Points<input name="points" type="number" min="1" max="1000" value="${q.points||100}" required></label><label class="wide">Fichier audio ou image <span class="mini">· max. 30 Mo</span><input name="media" type="file" accept="audio/*,image/*"><span class="mini">${editing&&q.mediaKey?'Un fichier est déjà associé. Laissez vide pour le garder.':'Votre fichier reste sur ce PC.'}</span></label></div><button class="btn primary full" type="submit" style="margin-top:23px">Enregistrer la question</button></form>`);}
function modal(html){$('.dialog')?.remove();const d=document.createElement('div');d.className='dialog';d.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${html}</div>`;document.body.append(d);d.querySelector('input,button')?.focus();}
function closeModal(){$('.dialog')?.remove();}
async function prepareImage(){const q=currentQ();if(!q)return;let url=q.imageUrl;if(!url&&q.mediaKey){if(!assetUrls.has(q.mediaKey)){const b=await getBlob(q.mediaKey);if(b?.type.startsWith('image/'))assetUrls.set(q.mediaKey,URL.createObjectURL(b));}url=assetUrls.get(q.mediaKey);}if(url&&$('[data-image]')){$('[data-image]').innerHTML=`<img src="${esc(url)}" alt="Image mystère à identifier" data-mystery>`;}}
function broadcastTV(){if(!game||role!=='host')return;const s=publicGame(game),q=currentQ();s.effect=game.effect||config.effect;if(q?.mediaKey&&assetUrls.has(q.mediaKey)){s.question={...s.question,mediaKind:'image',imageUrl:assetUrls.get(q.mediaKey)};}channel.postMessage({type:'state',state:s});}
async function receive(){
 const ev=game?.event;if(ev&&ev.id!==lastEvent){if(['correct','podium'].includes(ev.type)||game.mode==='phone'&&game.phase==='reveal'&&Object.values(game.answers||{}).some(r=>r.total>0))celebrate();if(role==='host')desk.jingle(ev.type);}
 if(role==='host'&&game.phase!=='playing')desk.pause();
 lastEvent=ev?.id;seenCount=null;render();await prepareImage();if(role==='host'){broadcastTV();if(game.mode==='usb')write('declic.localGame',game);}
}
async function ensureAudio(){const q=currentQ();if(!q)return;if(desk.id===q.id&&audioReady)return;audioReady=false;audioError='';await desk.load(q,q.mediaKey?await getBlob(q.mediaKey):null,game.effect||config.effect);audioReady=true;}
function send(action){if(action.type==='answer')action.questionId=currentQ()?.id;if(game?.mode==='phone'){if(!ws||ws.readyState!==WebSocket.OPEN){toast('Connexion interrompue. Attendez la reconnexion.');return;}ws.send(JSON.stringify(action));}else{const next=applyAction(game,action);if(next!==game){game=next;void receive();}}}
async function launch(){if(busy)return;busy=true;catalogMessage='';audioError='';render();
 try{
 if(config.source==='catalog'&&config.universe==='music'&&(!catalogPool.tracks.length||config.catalogFrom!=='explorer'&&catalogPool.themeKey!==config.themes.join(',')))await loadThemes();
 let qs=selectedQuestions();if(!qs.length)throw Error(config.challenge==='artistTitle'?'Il faut au moins 4 titres du même artiste pour ce défi. Recherchez un artiste dans Les musiques.':'Aucun contenu jouable dans cette sélection. Ajoutez des titres ou choisissez Découverte.');
 if(config.effect==='image'){qs=qs.filter(q=>q.kind==='image'||q.artwork);if(!qs.length)throw Error('Choisissez des questions avec une image ou des pochettes pour cet effet.');}
 if(config.mode==='usb'){const keys=config.teams.map(t=>t.key.toLowerCase());if(keys.some(k=>!k.trim())||new Set(keys).size!==keys.length)throw Error('Attribuez une touche différente à chaque équipe.');if(config.teams.some(t=>!t.name.trim()))throw Error('Donnez un nom à chaque équipe.');}
 await desk.unlock();clearTimeout(reconnect);if(ws){ws.onclose=null;ws.close();ws=null;}desk.stop();desk.id=null;audioReady=false;lastEvent=null;role='host';replyDraft={};
 const questions=qs.map(q=>({...q,duration:Math.min(q.audioUrl?30:90,config.duration),target:q.target,artwork:q.artwork}));
 if(config.mode==='usb'){room=null;game=createGame(questions,config.teams,'usb','text',config.settings);game.effect=config.effect;view='studio';await receive();return;}
 const clean=questions.map(({mediaKey,mediaType,notes,audioUrl,...q})=>q);const res=await fetch('/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({questions:clean,input:config.input,settings:config.settings,effect:config.effect})});const data=await res.json();if(!res.ok)throw Error(data.error);room=data.code;auth={type:'host',token:data.token};write('declic.host',{room,token:data.token,effect:config.effect,questions});game=null;view='studio';connect();
 }catch(e){catalogMessage=e.message||'Impossible de préparer la partie.';toast(catalogMessage);view='home';}finally{busy=false;render();}
}
function connect(){clearTimeout(reconnect);if(ws){ws.onclose=null;ws.close();}connected=false;ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/api/rooms/${room}`);const socket=ws;
 socket.onopen=()=>{connected=true;socket.send(JSON.stringify(auth));};
 socket.onmessage=e=>{if(e.data==='pong')return;try{const m=JSON.parse(e.data);if(m.type==='error'){busy=false;toast(m.message);if(view==='join')render();if(/expir|introuvable|refus|commencé|déjà|maximum|Entrez/.test(m.message)){socket.onclose=null;socket.close();connected=false;}return;}if(m.type==='session'){teamId=m.id;sessionStorage.setItem('declic.player.'+room,JSON.stringify({id:m.id,token:m.token}));auth={type:'join',token:m.token};role='player';view='phone';busy=false;}if(m.type==='state'){game=m.state;game.teams=game.teams.map(t=>({id:t.id,name:t.name,score:t.score,key:t.key,streak:t.streak}));if(role==='host'){const saved=read('declic.host',{});if(saved.room===room){game.effect=saved.effect;game.questions=game.questions.map(q=>({...q,...saved.questions?.find(v=>v.id===q.id)}));}}void receive();}}catch{toast('Erreur de synchronisation.');}};
 socket.onclose=()=>{connected=false;busy=false;if(view==='join'){toast('Partie introuvable ou indisponible. Vérifiez le code.');render();return;}render();reconnect=setTimeout(()=>connect(),2500);};socket.onerror=()=>{};
}
setInterval(()=>{if(ws?.readyState===WebSocket.OPEN)ws.send('ping');},25000);
setInterval(()=>{
 if(!game)return;const now=Date.now(), ph=game.phase;if(role==='host'&&game.mode==='usb'&&ph==='reveal'&&game.nextAt&&now>=game.nextAt){send({type:'next'});return;}
 if(ph==='playing'){
  const n=Math.max(0,Math.ceil((game.startAt-now)/1000));if(seenCount!==n){const previous=seenCount;seenCount=n;if(n||previous>0){render();void prepareImage();}if(n&&role==='host'&&n!==countdown){desk.jingle('tick');countdown=n;}}
  if(now>=game.startAt&&role==='host'&&audioReady&&now<game.endAt)desk.play();
  if(now>=game.endAt&&role==='host'&&game.mode==='usb'){send({type:'timeout'});return;}
 }
 const q=currentQ(),duration=(q?.duration||30)*1000,remaining=['buzzed','paused'].includes(ph)?game.remaining:Math.max(0,game.endAt-now), pct=ph==='playing'?Math.min(100,remaining/duration*100):ph==='reveal'?0:100;
 document.querySelectorAll('[data-time]').forEach(el=>el.textContent=ph==='playing'?(now<game.startAt?'Préparez-vous':Math.ceil(remaining/1000)+' s'):['buzzed','paused'].includes(ph)?'En pause':ph==='reveal'?'Réponse révélée':'À vous de jouer');document.querySelectorAll('[data-progress]').forEach(el=>el.style.width=pct+'%');
 document.querySelectorAll('[data-mystery]').forEach(el=>el.style.filter=((game.effect||config.effect)==='image'||q?.target==='cover')&&ph!=='reveal'?`blur(${ph==='playing'?Math.max(0,remaining/duration*22):22}px)`:'none');
},150);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const act=b.dataset.action,v=b.dataset.value;
 try{
 if(act==='close-modal'){closeModal();return;}
 if(act==='fullscreen'){if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();return;}
 if(act==='sound'){desk.muted=!desk.muted;render();return;}
 if(act==='home'){if(role!=='host'&&game)return;view='home';render();return;}
 if(act==='library'||act==='help'){view=act;render();return;}
 if(act==='universe'){config.universe=v;saveConfig();render();return;}
 if(act==='effect'){config.effect=v;saveConfig();render();return;}
 if(act==='mode'){config.mode=v;if(v==='phone'&&config.input==='qcm'&&config.challenge==='both')config.challenge='title';saveConfig();render();return;}
 if(act==='add-team'){const id=crypto.randomUUID();config.teams.push({id,name:'Équipe '+(config.teams.length+1),key:'1234567890'.split('').find(k=>!config.teams.some(t=>t.key===k))});saveConfig();render();return;}
 if(act==='remove-team'){config.teams.splice(Number(v),1);saveConfig();render();return;}
 if(act==='launch'){await launch();return;}
 if(act==='resume-phone'){const saved=read('declic.host',null);if(saved){room=saved.room;auth={type:'host',token:saved.token};role='host';view='studio';await desk.unlock();connect();render();}return;}
 if(act==='resume'){const s=read('declic.localGame',null);if(s&&s.version!==2){toast('Cette ancienne partie ne peut pas être reprise. Lancez une nouvelle soirée.');return;}if(s){ws?.close();ws=null;room=null;game=s;role='host';view='studio';desk.id=null;await desk.unlock();await receive();}return;}
 if(act==='new-game'){desk.stop();view='home';render();return;}
 if(act==='screen'){const win=window.open('/tv','declic-public','width=1280,height=800');if(!win)toast('Autorisez les fenêtres pour ouvrir l’écran public.');return;}
 if(act==='copy-link'){await navigator.clipboard.writeText(location.origin+'/join?code='+room);toast('Lien d’invitation copié !');return;}
 if(act==='join-page'){desk.stop();view='join';room=null;render();return;}
 if(act==='new-question'){questionForm({universe:config.universe});return;}
 if(act==='edit-question'){questionForm(custom.find(q=>q.id===v));return;}
 if(act==='delete-question'){const q=custom.find(q=>q.id===v);modal(`<h2>Retirer cette question ?</h2><p class="help">${esc(q?.prompt)}</p><p class="mini">Vous pourrez la recréer ou la réimporter depuis votre export.</p><div class="row" style="margin-top:22px"><button class="btn ghost" data-action="close-modal">Garder</button><button class="btn primary" data-action="confirm-delete" data-value="${esc(v)}">Retirer</button></div>`);return;}
 if(act==='confirm-delete'){custom=custom.filter(q=>q.id!==v);write('declic.library',custom);closeModal();render();toast('Question retirée.');return;}
 if(act==='export'){const blob=new Blob([JSON.stringify({version:1,questions:custom},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='declic-questions.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);return;}
 if(act==='adjust'){modal(`<div class="top"><h2>Ajuster un score</h2><button class="iconbtn" data-action="close-modal" aria-label="Fermer">×</button></div><form id="adjust-form"><label class="field-label" for="adjustteam">Équipe</label><select name="team" id="adjustteam">${game.teams.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select><label class="field-label" for="adjustpoints">Points à ajouter ou retirer</label><input id="adjustpoints" name="points" type="number" min="-1000" max="1000" value="100" required><button class="btn primary full" type="submit" style="margin-top:20px">Appliquer</button></form>`);return;}
 if(act==='answer'){if(Date.now()>=game.endAt){toast('Le temps est écoulé !');return;}send({type:'answer',answer:v});return;}
 if(['play','pause','resume','good','bad','reveal','next'].includes(act)){await desk.unlock();if(act==='play'){busy=true;render();try{await ensureAudio();}catch(error){audioError=error.message;toast(audioError);return;}finally{busy=false;render();}}send(act==='good'||act==='bad'?{type:'judge',correct:act==='good'}:{type:act});return;}
 }catch(err){toast(err.message||'Cette action n’a pas pu être effectuée.');}
});
document.addEventListener('input',e=>{if(e.target.dataset.team!==undefined){config.teams[Number(e.target.dataset.team)].name=e.target.value;saveConfig();}if(e.target.dataset.key!==undefined){config.teams[Number(e.target.dataset.key)].key=e.target.value.toLowerCase();saveConfig();}});
document.addEventListener('change',async e=>{
 if(e.target.id==='source'){config.source=e.target.value;saveConfig();render();}
 if(e.target.id==='inputmode'){config.input=e.target.value;if(config.input==='qcm'&&config.challenge==='both')config.challenge='title';saveConfig();render();}
 if(e.target.id==='import-json')try{const file=e.target.files[0];if(!file)return;if(file.size>1e6)throw Error('Le JSON doit faire moins de 1 Mo.');const data=JSON.parse(await file.text());if(!Array.isArray(data.questions)||data.questions.length>100)throw Error('Le fichier doit contenir une liste de 100 questions maximum.');const imported=data.questions.map(q=>{if(!['music','film'].includes(q.universe)||!['audio','image','question'].includes(q.kind)||typeof q.prompt!=='string'||q.prompt.length>300||typeof q.answer!=='string'||!q.answer.trim()||q.answer.length>180||!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>typeof o!=='string'||o.length>180)||!q.options.includes(q.answer)||!Number.isFinite(q.duration)||q.duration<5||q.duration>90||!Number.isFinite(q.points)||q.points<1||q.points>1000)throw Error('Une question est invalide. Aucun import effectué.');return {id:crypto.randomUUID(),universe:q.universe,kind:q.kind,prompt:q.prompt,answer:q.answer,aliases:(Array.isArray(q.aliases)?q.aliases:[]).filter(x=>typeof x==='string').map(x=>x.slice(0,180)),options:q.options,duration:q.duration,points:q.points,emoji:typeof q.emoji==='string'?q.emoji.slice(0,80):undefined};});custom.push(...imported);write('declic.library',custom);render();toast('Questions importées. Réassociez les fichiers dans l’éditeur.');}catch(err){toast(err.message);}
});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=new FormData(f);
 if(f.id==='question-form')try{const answer=String(data.get('answer')).trim(),wrong=String(data.get('wrong')).split('\n').map(x=>x.trim()).filter(Boolean);if(!answer||wrong.length!==3||new Set([answer,...wrong].map(x=>x.toLowerCase())).size!==4)throw Error('Saisissez une bonne réponse et trois mauvaises réponses différentes.');const existing=custom.find(q=>q.id===f.dataset.id),id=existing?.id||crypto.randomUUID();let mediaKey=existing?.mediaKey,mediaType=existing?.mediaType;const file=data.get('media'),kind=data.get('kind');if(file?.size){if(file.size>30*1024*1024)throw Error('Le fichier doit faire moins de 30 Mo.');if(kind==='audio'&&!file.type.startsWith('audio/'))throw Error('Choisissez un fichier audio pour ce type de question.');if(kind==='image'&&!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw Error('Choisissez une image JPG, PNG, WebP ou GIF.');mediaKey=id;mediaType=file.type;await storeBlob(id,file);if(assetUrls.has(id)){URL.revokeObjectURL(assetUrls.get(id));assetUrls.delete(id);}}if(kind==='audio'&&(!mediaKey||!mediaType?.startsWith('audio/')))throw Error('Ajoutez un fichier audio.');if(kind==='image'&&(!mediaKey||!mediaType?.startsWith('image/')))throw Error('Ajoutez une image.');const options=[answer,...wrong];for(let i=3;i>0;i--){const j=Math.floor(Math.random()*(i+1));[options[i],options[j]]=[options[j],options[i]];}const q={id,universe:data.get('universe'),kind,prompt:String(data.get('prompt')).trim(),answer,aliases:String(data.get('aliases')).split(';').map(x=>x.trim()).filter(Boolean),options,duration:Number(data.get('duration')),points:Number(data.get('points')),mediaKey,mediaType,title:String(data.get('title')||'').trim()||undefined,artist:String(data.get('artist')||'').trim()||undefined,target:'both'};custom=existing?custom.map(v=>v.id===id?q:v):[...custom,q];write('declic.library',custom);closeModal();render();toast('Question enregistrée !');}catch(err){toast(err.message);}
 if(f.id==='join-form'){const code=String(data.get('code')).trim().toUpperCase();if(!/^[A-Z2-9]{8}$/.test(code)){toast('Entrez le code de 8 caractères.');return;}room=code;const saved=JSON.parse(sessionStorage.getItem('declic.player.'+room)||'null');auth={type:'join',name:String(data.get('name')).trim(),token:saved?.token};teamId=saved?.id;busy=true;render();connect();}
 if(f.id==='answer-form'){send({type:'answer',answer:String(data.get('answer')||'').trim(),title:String(data.get('title')||'').trim(),artist:String(data.get('artist')||'').trim()});}
 if(f.id==='adjust-form'){send({type:'adjust',team:data.get('team'),points:Number(data.get('points'))});closeModal();}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){closeModal();return;}
 if(role!=='host'||view!=='studio'||game?.mode!=='usb'||e.repeat||e.target.closest('input,textarea,select')||$('.dialog'))return;
 const t=game.teams.find(t=>t.key.toLowerCase()===e.key.toLowerCase());if(!t)return;e.preventDefault();if(game.phase==='lobby'){toast(t.name+' : buzzer reconnu !');void desk.unlock().then(()=>desk.jingle('buzz'));return;}send({type:'buzz',team:t.id});
});
function catalogScreen(){return `<main class="library"><div class="row"><div><span class="eyebrow">LA BOÎTE À TUBES</span><h1>Trouvez les sons de votre soirée.</h1><p class="help">Recherche de titres et de playlists Deezer. Les extraits sont écoutés à la demande.</p></div><button class="btn primary right" data-action="v2-use-catalog">Utiliser ma sélection →</button></div><form id="catalog-search" class="catalog-search"><input name="query" placeholder="Un artiste, un titre…" aria-label="Rechercher des musiques" value="${esc(catalogQuery)}" minlength="2" required maxlength="120"><select name="type" aria-label="Type de recherche"><option value="tracks" ${catalogSearchType==='tracks'?'selected':''}>Titres</option><option value="playlists" ${catalogSearchType==='playlists'?'selected':''}>Playlists</option></select><button class="btn primary" ${busy?'disabled':''}>Rechercher</button></form><form id="playlist-import" class="playlist-import"><label for="playlist-url">Ou collez le lien d’une playlist Deezer publique</label><div class="row"><input id="playlist-url" name="url" placeholder="https://www.deezer.com/fr/playlist/…" required><button class="btn ghost" ${busy?'disabled':''}>Importer</button></div></form>${catalogMessage?`<div class="catalog-message" role="status">${esc(catalogMessage)}</div>`:''}<div class="catalog-meta"><strong>${esc(catalogPool.name||'Ma sélection')} · ${catalogPool.tracks.length} titre(s)</strong><div class="row"><button class="textbtn" data-action="v2-add-all" ${!catalogResults.tracks?.length?'disabled':''}>＋ Tous les résultats</button><button class="textbtn" data-action="v2-clear-pool" ${!catalogPool.tracks.length?'disabled':''}>Vider la sélection</button></div></div><div id="catalog-player" class="callout hidden" role="status"><span></span> <button class="btn ghost" data-action="v2-stop-preview">■ Arrêter l’écoute</button></div><div class="track-list">${(catalogSearchType==='playlists'?catalogResults.playlists:catalogResults.tracks||[]).map(t=>catalogSearchType==='playlists'?`<article class="track-row"><img src="${esc(t.artwork||'')}" alt="" loading="lazy"><div><strong>${esc(t.title)}</strong><small>${esc(t.author||'')} · ${t.tracks||'?'} titres</small></div><button class="btn ghost" data-action="v2-playlist" data-value="${esc(t.id)}">Importer</button></article>`:trackRow(t)).join('')}</div>${!catalogResults.tracks?.length&&!catalogResults.playlists?.length?'<div class="empty">Recherchez un artiste ou chargez vos thèmes depuis le studio.<br>Votre sélection est conservée dans ce navigateur.</div>':''}${catalogPool.tracks.length?`<div class="sectiontitle"><h2>Dans votre sélection</h2><span class="badge">${catalogPool.tracks.length} TITRES</span></div><div class="track-list">${catalogPool.tracks.map(t=>trackRow(t,true)).join('')}</div>`:''}<div class="callout">La connexion musicale active est Deezer. Spotify et Apple Music ne sont pas connectés dans cette version. Les fichiers audio personnels restent disponibles dans « Mes questions ».</div></main>`;}
function trackRow(t,inPool=false){const added=catalogPool.tracks.some(v=>v.id===t.id);return `<article class="track-row"><img src="${esc(t.artwork||'')}" alt="" loading="lazy"><div><strong>${esc(t.title)}</strong><small>${esc(t.artist)} ${t.explicit?'<b class="explicit">E</b>':''}</small><a href="${esc(t.link)}" target="_blank" rel="noopener noreferrer">Sur Deezer ↗</a></div><button class="btn ghost" data-action="v2-preview" data-value="${esc(t.id)}" aria-label="Écouter ${esc(t.title)}">▶</button><button class="btn ${inPool?'ghost':added?'good':'primary'}" data-action="${inPool?'v2-remove-track':'v2-add-track'}" data-value="${esc(t.id)}" ${!inPool&&added?'disabled':''}>${inPool?'Retirer':added?'✓ Ajouté':'＋ Ajouter'}</button></article>`;}
function scoreBreakdown(r){const labels={title:'Titre',artist:'Artiste',answer:'Réponse',speed:'Rapidité',streak:'Série'};return `<div class="score-breakdown">${Object.entries(r.breakdown||{}).filter(([,v])=>v>0).map(([id,v])=>`<span>${labels[id]} <b>+${v}</b></span>`).join('')}</div>`;}
function historyScreen(){return `<main class="library"><div class="row"><div><span class="eyebrow">CHAQUE DÉCLIC COMPTE</span><h1>Le bilan de la soirée.</h1></div><button class="btn ghost right" data-action="v2-return">Revenir au jeu</button><button class="btn primary" data-action="v2-export-results">Exporter le bilan</button></div><div class="results-leaders">${leaderboard()}</div>${(game?.history||[]).map(h=>`<details class="round-history" open><summary><span class="step">${h.index+1}</span>${esc(h.question.title||h.question.answer)}${h.question.artist?' · '+esc(h.question.artist):''}</summary>${h.results.map(t=>`<div class="history-team"><strong>${esc(t.name)}</strong><span>+${t.result.total||0} pts</span>${scoreBreakdown(t.result)}</div>`).join('')}</details>`).join('')||'<div class="empty">Le détail sera disponible après la première révélation.</div>'}</main>`;}
function persistPool(){write('declic.musicPool',catalogPool);}
async function apiJSON(path){const res=await fetch(path,{signal:AbortSignal.timeout(45000)});const data=await res.json();if(!res.ok)throw Error(data.error||'Le catalogue n’a pas répondu. Réessayez dans un instant.');return data;}
async function loadThemes(){catalogMessage='Recherche des extraits disponibles…';render();const key=config.themes.join(','),data=await apiJSON('/api/music/selection?themes='+encodeURIComponent(key));catalogPool={name:data.name,tracks:data.tracks,themeKey:key};config.catalogFrom='themes';config.source='catalog';persistPool();saveConfig();catalogMessage=`${data.tracks.length} titres avec un extrait disponible. Les titres seront mélangés au lancement.`;}
async function loadPlaylist(id){const data=await apiJSON('/api/music/playlist?id='+encodeURIComponent(id));if(!data.tracks.length)throw Error('Cette playlist ne contient pas d’extrait disponible. Essayez une autre sélection.');catalogPool={name:data.name,tracks:data.tracks,themeKey:''};config.catalogFrom='explorer';config.source='catalog';catalogResults={tracks:data.tracks,playlists:[]};catalogSearchType='tracks';persistPool();saveConfig();catalogMessage=`${data.tracks.length} titres jouables importés${data.limited?' parmi les 100 premiers de la playlist':''}.`;}
async function withBusy(task){if(busy)return;busy=true;render();try{await task();}catch(e){catalogMessage=e.message||'Impossible de charger cette sélection.';toast(catalogMessage);}finally{busy=false;render();}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const act=b.dataset.action,v=b.dataset.value;
 if(view==='catalog'&&act!=='v2-preview'){desk.stop();$('#catalog-player')?.classList.add('hidden');}
 if(act==='v2-catalog'){view='catalog';render();}
 if(act==='v2-return'){view=role==='player'?'phone':'studio';render();}
 if(act==='v2-history'){view='history';render();}
 if(act==='v2-export-results'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({name:'Déclic !',date:new Date().toISOString(),teams:game.teams.map(({id,name,score})=>({id,name,score})),rounds:game.history},null,2)],{type:'application/json'}));a.download='declic-bilan.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
 if(act==='v2-theme'){if(config.themes.includes(v)){if(config.themes.length===1){toast('Gardez au moins une ambiance.');return;}config.themes=config.themes.filter(id=>id!==v);}else{if(config.themes.length>=3){toast('Vous pouvez mélanger jusqu’à trois ambiances.');return;}config.themes.push(v);}config.catalogFrom='themes';config.source='catalog';saveConfig();render();}
 if(act==='v2-challenge'){config.challenge=v;saveConfig();render();}
 if(act==='v2-load-themes')await withBusy(loadThemes);
 if(act==='v2-use-catalog'){if(!catalogPool.tracks.length){toast('Ajoutez des titres ou importez une playlist.');return;}config.catalogFrom='explorer';config.source='catalog';config.universe='music';saveConfig();view='home';render();}
 if(act==='v2-add-track'){const t=catalogResults.tracks.find(t=>t.id===v);if(t&&!catalogPool.tracks.some(x=>x.id===v)){if(catalogPool.tracks.length>=100){toast('100 titres maximum par sélection.');return;}catalogPool={name:'Ma sélection',tracks:[...catalogPool.tracks,t],themeKey:''};config.catalogFrom='explorer';config.source='catalog';persistPool();saveConfig();render();}}
 if(act==='v2-remove-track'){catalogPool.tracks=catalogPool.tracks.filter(t=>t.id!==v);persistPool();render();}
 if(act==='v2-add-all'){const all=[...new Map([...catalogPool.tracks,...catalogResults.tracks].map(t=>[t.id,t])).values()].slice(0,100);catalogPool={name:'Ma sélection',tracks:all,themeKey:''};config.catalogFrom='explorer';persistPool();saveConfig();render();}
 if(act==='v2-clear-pool'){catalogPool={name:'',tracks:[],themeKey:''};persistPool();render();}
 if(act==='v2-playlist')await withBusy(()=>loadPlaylist(v));
 if(act==='v2-stop-preview'){desk.stop();$('#catalog-player')?.classList.add('hidden');}
 if(act==='v2-preview'){const t=[...(catalogResults.tracks||[]),...catalogPool.tracks].find(t=>t.id===v),player=$('#catalog-player');if(t&&player){player.classList.remove('hidden');player.querySelector('span').textContent='Chargement de '+t.title+'…';try{await desk.load({id:'preview-'+v,audioUrl:t.preview},null,'normal');if($('#catalog-player')!==player||player.classList.contains('hidden')||desk.id!=='preview-'+v)return;desk.play();if(desk.source)desk.source.loop=false;player.querySelector('span').textContent='♫ '+t.title+' · '+t.artist;}catch(err){player.querySelector('span').textContent=err.message;}}}
 if(act==='v2-judge'){await desk.unlock();send({type:'judge',correct:true,part:v});}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.config){const k=el.dataset.config;config[k]=k==='explicit'?!el.checked:['count','duration'].includes(k)?Number(el.value):el.value;saveConfig();if(k!=='explicit')render();}if(el.dataset.setting){const k=el.dataset.setting;config.settings[k]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;config.settings=gameSettings(config.settings);saveConfig();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['catalog-search','playlist-import'].includes(form.id))return;e.preventDefault();const data=new FormData(form);
 if(form.id==='catalog-search'){catalogQuery=String(data.get('query')).trim();catalogSearchType=data.get('type');catalogMessage='Recherche en cours…';await withBusy(async()=>{catalogResults=await apiJSON('/api/music/search?q='+encodeURIComponent(catalogQuery)+'&type='+catalogSearchType);catalogMessage=catalogSearchType==='playlists'?`${catalogResults.playlists.length} playlist(s) trouvée(s).`:`${catalogResults.tracks.length} titre(s) avec un extrait disponible.`;});}
 if(form.id==='playlist-import'){const value=String(data.get('url')).trim();let id=value;if(!/^\d+$/.test(id)){try{const u=new URL(value);if(!/(^|\.)deezer\.com$/.test(u.hostname))throw Error();id=u.pathname.match(/\/playlist\/(\d+)/)?.[1];}catch{id=null;}}if(!id){catalogMessage='Collez un lien complet de playlist Deezer publique (deezer.com/…/playlist/123). Les liens Spotify ne sont pas pris en charge.';render();return;}await withBusy(()=>loadPlaylist(id));}
});
const params=new URLSearchParams(location.search);
if(location.pathname==='/tv'){role='tv';view='tv';channel.postMessage({type:'request'});}
else if(location.pathname==='/join'){view='join';room=(params.get('code')||'').toUpperCase();}
render();
